        >
          <motion.div
            whileHover={{ scale: 1.1, rotate: 5 }}
            transition={springTransition}
            className={cn(
              "h-8 w-8 rounded-lg flex items-center justify-center",
              variantStyles[item.variant],
            )}
          >
            <item.icon className="h-4 w-4" />
