}

export default function ContentModerationPage() {
  const [activeTab, setActiveTab] = useState("moderation");
  const [posts, setPosts] = useState<Post[]>(MOCK_POSTS);
  const [flaggedComments, setFlaggedComments] = useState<Comment[]>(
    MOCK_FLAGGED_COMMENTS,
  );
  const [stats] = useState<ModerationStats>(MOCK_STATS);
  const [isLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterVisibility, setFilterVisibility] = useState("all");
  const [filterType, setFilterType] = useState("all");
  const [sortBy, setSortBy] = useState("newest");
  const [isRefreshing, setIsRefreshing] = useState(false);

  const flaggedPosts = useMemo(
    () => posts.filter((p) => p.isFlagged || p.status === "pending_review"),
    [posts],
  );

  const handleRefresh = async () => {
    setIsRefreshing(true);
    await new Promise((resolve) => setTimeout(resolve, 1000));
    setIsRefreshing(false);
    toast.success("Feed refreshed");
  };

  const handlePostAction = useCallback(
    (postId: string, action: ModerationAction, reason?: string) => {
      setPosts((prev) =>
        prev.map((post) => {
          if (post.id === postId) {
            switch (action) {
              case "approve":
                toast.success("Post approved");
                return {
                  ...post,
                  status: "published" as PostStatus,
                  isFlagged: false,
                  flagReason: undefined,
                };
              case "hide":
                toast.success("Post hidden");
                return { ...post, status: "hidden" as PostStatus };
              case "flag":
                toast.success("Post flagged for review");
                return { ...post, isFlagged: true, flagReason: reason };
              case "delete":
                toast.success("Post deleted");
                return post;
              default:
                return post;
            }
          }
          return post;
        }),
      );

      if (action === "delete") {
        setPosts((prev) => prev.filter((p) => p.id !== postId));
      }
    },
    [],
  );

  const handleCommentAction = useCallback(
    (commentId: string, action: "approve" | "delete") => {
      if (action === "delete") {
        setFlaggedComments((prev) => prev.filter((c) => c.id !== commentId));
        toast.success("Comment deleted");
      } else {
        setFlaggedComments((prev) => prev.filter((c) => c.id !== commentId));
        toast.success("Comment approved");
      }
    },
    [],
  );

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.3 }}
      className="p-4 sm:p-6 pb-20 space-y-6 sm:space-y-8"
    >
      <PageHeader
        title="Ministry Updates Moderation"
        description="Review flagged content, moderate posts, and manage comments."
      >
        <Link href="/mc/feed/org-updates">
          <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
            <Button className="h-9 gap-2 rounded-xl font-semibold">
              <PenSquare className="h-4 w-4" />
              <span className="hidden sm:inline">Org Updates</span>
            </Button>
          </motion.div>
        </Link>
        <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
          <Button variant="outline" size="sm" className="h-9 gap-2 rounded-xl">
            <Download className="h-4 w-4" />
            <span className="hidden sm:inline">Export</span>
          </Button>
        </motion.div>
        <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
          <Button
            variant="outline"
            size="icon"
            className="h-9 w-9 rounded-xl"
            onClick={handleRefresh}
            disabled={isRefreshing}
          >
            <RefreshCw
              className={cn("h-4 w-4", isRefreshing && "animate-spin")}
            />
          </Button>
        </motion.div>
      </PageHeader>

      <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-7 gap-3 sm:gap-4">
        <StatCard
          label="Total Posts"
          value={stats.totalPosts}
          icon={Activity}
          index={0}
        />
        <StatCard
          label="Flagged"
          value={stats.flaggedPosts}
          icon={Flag}
          variant="warning"
          index={1}
        />
        <StatCard
          label="Hidden"
          value={stats.hiddenPosts}
          icon={EyeOff}
          index={2}
        />
        <StatCard
          label="Pending"
          value={stats.pendingReview}
          icon={Clock}
          variant="warning"
          index={3}
        />
        <StatCard
          label="Comments"
          value={stats.totalComments}
          icon={MessageCircle}
          index={4}
        />
        <StatCard
          label="Flagged Comments"
          value={stats.flaggedComments}
          icon={AlertTriangle}
          variant={stats.flaggedComments > 0 ? "danger" : "default"}
          index={5}
        />
        <StatCard
          label="Actions Today"
          value={stats.actionsToday}
          icon={ShieldCheck}
          variant="success"
          index={6}
        />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-6 sm:gap-8">
        <div className="xl:col-span-8 space-y-6">
          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
              className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mb-4 sm:mb-6"
            >
              <TabsList className="bg-muted/50 p-1 rounded-xl h-auto border backdrop-blur-sm">
                <TabsTrigger
                  value="moderation"
                  className="rounded-lg px-3 sm:px-4 py-2 sm:py-2.5 font-semibold text-[9px] sm:text-[10px] uppercase tracking-wider data-[state=active]:bg-card data-[state=active]:shadow-sm data-[state=active]:text-foreground text-muted-foreground transition-all"
                >
                  <ShieldAlert className="h-3.5 w-3.5 sm:h-4 sm:w-4 mr-1.5 sm:mr-2" />
                  Queue
                  <AnimatePresence>
                    {flaggedPosts.length > 0 && (
                      <motion.div
                        initial={{ scale: 0 }}
                        animate={{ scale: 1 }}
                        exit={{ scale: 0 }}
                        transition={springTransition}
                      >
                        <Badge className="ml-2 h-4 sm:h-5 px-1.5 sm:px-2 text-[8px] sm:text-[9px] bg-amber-500 text-white rounded-full font-semibold border-0">
                          {flaggedPosts.length}
                        </Badge>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </TabsTrigger>
                <TabsTrigger
                  value="all"
                  className="rounded-lg px-3 sm:px-4 py-2 sm:py-2.5 font-semibold text-[9px] sm:text-[10px] uppercase tracking-wider data-[state=active]:bg-card data-[state=active]:shadow-sm data-[state=active]:text-foreground text-muted-foreground transition-all"
                >
                  <Globe className="h-3.5 w-3.5 sm:h-4 sm:w-4 mr-1.5 sm:mr-2" />
                  All Posts
                </TabsTrigger>
              </TabsList>

              <AnimatePresence mode="wait">
                {activeTab === "all" && (
                  <motion.div
                    initial={{ opacity: 0, x: 20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 20 }}
                    className="flex items-center gap-2 w-full sm:w-auto"
                  >
                    <div className="relative flex-1 sm:flex-none">
                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                      <Input
                        placeholder="Search posts..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-9 h-9 sm:h-10 w-full sm:w-56 lg:w-64 rounded-xl"
                      />
                      {searchQuery && (
                        <motion.button
                          initial={{ scale: 0 }}
                          animate={{ scale: 1 }}
                          exit={{ scale: 0 }}
                          onClick={() => setSearchQuery("")}
                          className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                        >
                          <X className="h-3.5 w-3.5" />
                        </motion.button>
                      )}
                    </div>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <motion.div
                          whileHover={{ scale: 1.02 }}
                          whileTap={{ scale: 0.98 }}
                        >
                          <Button
                            variant="outline"
                            size="sm"
                            className="h-9 sm:h-10 gap-2 rounded-xl"
                          >
                            <Filter className="h-4 w-4" />
                            <span className="hidden sm:inline">Filter</span>
                          </Button>
                        </motion.div>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent
                        align="end"
                        className="w-56 rounded-xl p-1.5"
                      >
                        <DropdownMenuLabel className="text-[10px] uppercase tracking-wider font-semibold px-2">
                          Visibility
                        </DropdownMenuLabel>
                        <DropdownMenuCheckboxItem
                          checked={filterVisibility === "all"}
                          onCheckedChange={() => setFilterVisibility("all")}
                          className="rounded-lg"
                        >
                          All
                        </DropdownMenuCheckboxItem>
                        <DropdownMenuCheckboxItem
                          checked={filterVisibility === "public"}
                          onCheckedChange={() => setFilterVisibility("public")}
                          className="rounded-lg"
                        >
                          Public
                        </DropdownMenuCheckboxItem>
                        <DropdownMenuCheckboxItem
                          checked={filterVisibility === "partners"}
                          onCheckedChange={() =>
                            setFilterVisibility("partners")
                          }
                          className="rounded-lg"
                        >
                          Partners
                        </DropdownMenuCheckboxItem>
                        <DropdownMenuCheckboxItem
                          checked={filterVisibility === "private"}
                          onCheckedChange={() => setFilterVisibility("private")}
                          className="rounded-lg"
                        >
                          Private
                        </DropdownMenuCheckboxItem>
                        <DropdownMenuSeparator />
                        <DropdownMenuLabel className="text-[10px] uppercase tracking-wider font-semibold px-2">
                          Type
                        </DropdownMenuLabel>
                        <DropdownMenuCheckboxItem
                          checked={filterType === "all"}
                          onCheckedChange={() => setFilterType("all")}
                          className="rounded-lg"
                        >
                          All Types
                        </DropdownMenuCheckboxItem>
                        <DropdownMenuCheckboxItem
                          checked={filterType === "update"}
                          onCheckedChange={() => setFilterType("update")}
                          className="rounded-lg"
                        >
                          Updates
                        </DropdownMenuCheckboxItem>
                        <DropdownMenuCheckboxItem
                          checked={filterType === "prayer request"}
                          onCheckedChange={() =>
                            setFilterType("prayer request")
                          }
                          className="rounded-lg"
                        >
                          Prayer Requests
                        </DropdownMenuCheckboxItem>
                        <DropdownMenuCheckboxItem
                          checked={filterType === "story"}
                          onCheckedChange={() => setFilterType("story")}
                          className="rounded-lg"
                        >
                          Stories
                        </DropdownMenuCheckboxItem>
                        <DropdownMenuCheckboxItem
                          checked={filterType === "announcement"}
                          onCheckedChange={() => setFilterType("announcement")}
                          className="rounded-lg"
                        >
                          Announcements
                        </DropdownMenuCheckboxItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                    <Select value={sortBy} onValueChange={setSortBy}>
                      <SelectTrigger className="h-9 sm:h-10 w-28 sm:w-36 rounded-xl">
                        <ArrowUpDown className="h-4 w-4 mr-2" />
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent className="rounded-xl">
                        <SelectItem value="newest" className="rounded-lg">
                          Newest
                        </SelectItem>
                        <SelectItem value="oldest" className="rounded-lg">
                          Oldest
                        </SelectItem>
                        <SelectItem value="engagement" className="rounded-lg">
                          Engagement
                        </SelectItem>
                      </SelectContent>
                    </Select>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>

            <TabsContent value="moderation" className="mt-0">
              <ModerationQueue
                posts={flaggedPosts}
                onAction={handlePostAction}
                isLoading={isLoading}
              />
            </TabsContent>

            <TabsContent value="all" className="mt-0">
              <AllPostsFeed
                posts={posts}
                searchQuery={searchQuery}
                filterVisibility={filterVisibility}
                filterType={filterType}
                sortBy={sortBy}
                onAction={handlePostAction}
              />
            </TabsContent>
          </Tabs>
        </div>

        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 0.3 }}
          className="xl:col-span-4 space-y-6"
        >
          <MotionCard
            whileHover={{ y: -2 }}
            transition={springTransition}
            className="rounded-2xl border shadow-sm"
          >
            <CardHeader className="pb-4">
              <div className="flex items-center gap-3">
                <motion.div
                  whileHover={{ scale: 1.1, rotate: 5 }}
                  transition={springTransition}
                  className="h-10 w-10 sm:h-11 sm:w-11 rounded-xl bg-amber-100 flex items-center justify-center"
                >
                  <MessageCircle className="h-5 w-5 text-amber-600" />
                </motion.div>
                <div>
                  <h3 className="font-bold text-sm text-foreground">
                    Flagged Comments
                  </h3>
                  <p className="text-xs text-muted-foreground">
                    {flaggedComments.length} need review
                  </p>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <FlaggedCommentsPanel
                comments={flaggedComments}
                onAction={handleCommentAction}
              />
            </CardContent>
          </MotionCard>

          <MotionCard
            whileHover={{ y: -2 }}
            transition={springTransition}
            className="rounded-2xl border shadow-sm"
          >
            <CardHeader className="pb-4">
              <div className="flex items-center gap-3">
                <motion.div
                  whileHover={{ scale: 1.1, rotate: 5 }}
                  transition={springTransition}
                  className="h-10 w-10 sm:h-11 sm:w-11 rounded-xl bg-muted flex items-center justify-center"
                >
                  <Clock className="h-5 w-5 text-muted-foreground" />
                </motion.div>
                <div>
                  <h3 className="font-bold text-sm text-foreground">
                    Recent Activity
                  </h3>
                  <p className="text-xs text-muted-foreground">
                    Moderation actions
                  </p>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <RecentActivityPanel />
            </CardContent>
          </MotionCard>

          <MotionCard
            whileHover={{ y: -2, scale: 1.01 }}
            transition={springTransition}
            className="rounded-2xl border shadow-sm bg-gradient-to-br from-primary/5 to-primary/10"
          >
            <CardContent className="p-5">
              <div className="flex items-start gap-4">
                <motion.div
                  whileHover={{ scale: 1.1, rotate: 10 }}
                  transition={springTransition}
                  className="h-10 w-10 sm:h-11 sm:w-11 rounded-xl bg-primary/10 flex items-center justify-center shrink-0"
                >
                  <Sparkles className="h-5 w-5 text-primary" />
                </motion.div>
                <div className="space-y-2">
                  <h3 className="font-bold text-sm text-foreground">
                    AI Moderation
                  </h3>
                  <p className="text-xs text-muted-foreground leading-relaxed">
                    Automatic flagging is enabled. Content with potential policy
                    violations will be queued for review.
                  </p>
                  <motion.div whileHover={{ x: 4 }}>
                    <Button
                      variant="link"
                      size="sm"
                      className="h-auto p-0 text-xs font-semibold"
                    >
                      Configure Settings{" "}
                      <ChevronRight className="h-3 w-3 ml-1" />
                    </Button>
                  </motion.div>
                </div>
              </div>
            </CardContent>
          </MotionCard>
        </motion.div>
      </div>
    </motion.div>
  );
}

"use client";

import { Button } from "@asym/ui/components/shadcn/button";
import { Card } from "@asym/ui/components/shadcn/card";
import {
  Map,
  MapMarker,
  MarkerContent,
  MapControls,
} from "@asym/ui/components/shadcn/map";
import { PageShell } from "@asym/ui/components/shadcn/page-shell";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@asym/ui/components/shadcn/tabs";
import { Plus, MapPin, Table as TableIcon, Layers } from "lucide-react";
import React, { useState } from "react";
import { toast } from "sonner";

import type { Location } from "@/features/mission-control/locations/hooks/use-locations";

import { LocationEditor } from "@/features/mission-control/locations/components/LocationEditor";
import { LocationTable } from "@/features/mission-control/locations/components/LocationTable";
import {
  useLocations,
  useDeleteLocation,
} from "@/features/mission-control/locations/hooks/use-locations";

export default function LocationsPage() {
  const { data: locations, isLoading } = useLocations();
  const { mutate: deleteLocation } = useDeleteLocation();
  const [selectedLocation, setSelectedLocation] =
    useState<Partial<Location> | null>(null);
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [isAdding, setIsAdding] = useState(false);

  const handleMapClick = (e: any) => {
    if (isAdding) {
      const { lng, lat } = e.lngLat;
      setSelectedLocation({ lat, lng, type: "custom", status: "draft" });
      setIsEditorOpen(true);
      setIsAdding(false);
      toast.info("Drop confirmed. Now configure your location.");
    }
  };

  const handleEdit = (location: Location) => {
    setSelectedLocation(location);
    setIsEditorOpen(true);
  };

  const handleDelete = (id: string) => {
    if (confirm("Are you sure you want to delete this location?")) {
      deleteLocation(id);
      setIsEditorOpen(false);
    }
  };

  const actions = (
    <Button
      onClick={() => setIsAdding(!isAdding)}
      className={`h-14 px-8 font-black uppercase tracking-[0.2em] text-[10px] rounded-2xl transition-all shadow-2xl ${
        isAdding
          ? "bg-amber-500 hover:bg-amber-600 text-white animate-pulse"
          : "bg-zinc-900 text-white hover:bg-zinc-800"
      }`}
    >
      <Plus className="mr-3 h-4 w-4" />
      {isAdding ? "Click on Map to Drop Marker" : "Add Location"}
    </Button>
  );

  return (
    <PageShell
      badge="Strategic Map"
      title="Where We Work"
      description="Manage global ministry footprints and projects."
      actions={actions}
    >
      <Tabs defaultValue="map" className="space-y-8">
        <div className="flex justify-center">
          <TabsList className="bg-zinc-100/50 p-1.5 rounded-[1.5rem] h-auto border border-zinc-100">
            <TabsTrigger
              value="map"
              className="rounded-xl px-8 py-3 text-[10px] font-black uppercase tracking-widest data-[state=active]:bg-white data-[state=active]:shadow-sm transition-all"
            >
              <Layers className="mr-2 h-3.5 w-3.5" /> Map View
            </TabsTrigger>
            <TabsTrigger
              value="table"
              className="rounded-xl px-8 py-3 text-[10px] font-black uppercase tracking-widest data-[state=active]:bg-white data-[state=active]:shadow-sm transition-all"
            >
              <TableIcon className="mr-2 h-3.5 w-3.5" /> Data Table
            </TabsTrigger>
          </TabsList>
        </div>

        <TabsContent value="map" className="m-0">
          <Card className="relative h-[600px] rounded-[2.5rem] overflow-hidden border-zinc-100 shadow-2xl shadow-zinc-100 bg-zinc-50">
            <Map
              initialViewState={{
                longitude: 0,
                latitude: 20,
                zoom: 1.5,
              }}
              onClick={handleMapClick}
            >
              <MapControls />
              {locations?.map((loc) => (
                <MapMarker
                  key={loc.id}
                  longitude={loc.lng}
                  latitude={loc.lat}
                  onClick={() => handleEdit(loc)}
                >
                  <MarkerContent>
                    <div
                      className={`size-6 rounded-full border-4 border-white shadow-xl flex items-center justify-center transition-transform hover:scale-125 ${
                        loc.type === "missionary"
                          ? "bg-zinc-900"
                          : loc.type === "project"
                            ? "bg-blue-600"
                            : "bg-zinc-400"
                      }`}
                    >
                      <MapPin className="size-3 text-white" />
                    </div>
                  </MarkerContent>
                </MapMarker>
              ))}
            </Map>

            {isAdding && (
              <div className="absolute top-6 left-1/2 -translate-x-1/2 z-20 pointer-events-none">
                <div className="bg-amber-500 text-white text-[10px] font-black uppercase tracking-widest px-6 py-3 rounded-full shadow-2xl animate-bounce">
                  Add Mode Active: Click anywhere on map
                </div>
              </div>
            )}
          </Card>
        </TabsContent>

        <TabsContent value="table" className="m-0">
          <Card className="rounded-[2.5rem] overflow-hidden border-zinc-100 shadow-2xl shadow-zinc-100">
            <div className="p-8">
              <LocationTable
                data={locations || []}
                isLoading={isLoading}
                onEdit={handleEdit}
                onDelete={handleDelete}
              />
            </div>
          </Card>
        </TabsContent>
      </Tabs>

      <LocationEditor
        location={selectedLocation}
        isOpen={isEditorOpen}
        onOpenChange={setIsEditorOpen}
        onDelete={handleDelete}
      />
    </PageShell>
  );
}

