"use client";

import { type EmailStudioFullConfig } from "@asym/config/email-studio";
import {
  type PDFStudioFullConfig,
} from "@asym/config/pdf-studio";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@asym/ui/components/shadcn/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@asym/ui/components/shadcn/select";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@asym/ui/components/shadcn/alert-dialog";
import { Button } from "@asym/ui/components/shadcn/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  DropdownMenuShortcut,
} from "@asym/ui/components/shadcn/dropdown-menu";
import { Input } from "@asym/ui/components/shadcn/input";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@asym/ui/components/shadcn/tooltip";
import { Kbd } from "@asym/ui/components/shadcn/kbd";
import { Label } from "@asym/ui/components/shadcn/label";
import {
  ToggleGroup,
  ToggleGroupItem,
} from "@asym/ui/components/shadcn/toggle-group";
import { Separator } from "@asym/ui/components/shadcn/separator";
import { Textarea } from "@asym/ui/components/shadcn/textarea";
import { PDFStudioSetupStatus } from "@asym/ui/components/studio/PDFStudioSetupStatus";
import { UnlayerEditor } from "@asym/ui/components/studio/UnlayerEditor";
import { cn } from "@asym/ui/lib/utils";
import {
  FileText,
  Save,
  Download,
  Smartphone,
  Monitor,
  ChevronRight,
  Settings,
  FileCode,
  Undo2,
  Redo2,
  MoreHorizontal,
  Copy,
  Trash2,
  FolderOpen,
  Plus,
  Check,
  Maximize2,
  Minimize2,
  Sparkles,
  History,
  Layers,
  FileDown,
  Printer,
  RotateCcw,
  AlertCircle,
} from "lucide-react";
import React, {
  useRef,
  useState,
  useCallback,
  useEffect,
} from "react";
import { toast } from "sonner";

import type { PDFTemplateCategory } from "@/lib/pdf-studio";
import type { UnlayerDesignJSON } from "@asym/email/email-studio-types";
import type { UnlayerEditorHandle } from "@asym/ui/components/studio/UnlayerEditor";

import {
  PDF_TEMPLATE_CATEGORIES,
  PAGE_SIZES,
  ORIENTATIONS,
} from "@/lib/pdf-studio";

type PreviewDevice = "desktop" | "mobile";

interface PDFMetadata {
  id: string | null;
  name: string;
  description: string;
  category: PDFTemplateCategory;
  pageSize: "A4" | "Letter" | "Legal";
  orientation: "portrait" | "landscape";
}

const DEFAULT_DESIGN: UnlayerDesignJSON = {
  counters: { u_column: 1, u_row: 1 },
  body: {
    rows: [],
    values: {
      backgroundColor: "#ffffff",
      contentWidth: "816px",
    },
  },
};

export default function PDFStudio() {
  const editorRef = useRef<UnlayerEditorHandle>(null);
  const [isEditorReady, setIsEditorReady] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [previewDevice, setPreviewDevice] = useState<PreviewDevice>("desktop");
  const [showSaveDialog, setShowSaveDialog] = useState(false);
  const [showExportDialog, setShowExportDialog] = useState(false);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [exportedHtml, setExportedHtml] = useState<string>("");
  const [studioConfig, setStudioConfig] = useState<PDFStudioFullConfig | null>(
    null,
  );
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [copiedHtml, setCopiedHtml] = useState(false);
  const [currentDesign, setCurrentDesign] = useState<UnlayerDesignJSON | null>(
    null,
  );
  const [metadata, setMetadata] = useState<PDFMetadata>({
    id: null,
    name: "Untitled Document",
    description: "",
    category: "custom",
    pageSize: "Letter",
    orientation: "portrait",
  });

  const handleUndo = useCallback(() => {
    editorRef.current?.undo();
  }, []);

  const handleRedo = useCallback(() => {
    editorRef.current?.redo();
  }, []);

  const handleSaveClick = useCallback(() => {
    if (!editorRef.current) return;
    setShowSaveDialog(true);
  }, []);

  const handleExportHtml = useCallback(async () => {
    if (!editorRef.current) return;
    try {
      const data = await editorRef.current.exportHtml({
        minify: false,
        cleanup: studioConfig?.export.cleanupCss ?? true,
      });
      setExportedHtml(data.html);
      setShowExportDialog(true);
    } catch {
      toast.error("Failed to export HTML");
    }
  }, [studioConfig]);

  const handleExportPDF = useCallback(async () => {
    if (!editorRef.current) return;
    setIsExporting(true);
    try {
      const pdfResult = await editorRef.current.exportPdf();

      if (pdfResult?.url) {
        window.open(pdfResult.url, "_blank");
        toast.success("PDF exported successfully", {
          description: "Your PDF is ready for download",
          duration: 4000,
        });
      } else {
        toast.info("PDF export initiated", {
          description: "Your document is being prepared for download...",
          duration: 3000,
        });
      }
    } catch (error) {
      console.error("PDF export error:", error);
      toast.error("Failed to export PDF", {
        description:
          "PDF export requires an Unlayer project ID. Configure your Unlayer account for PDF export.",
      });
    } finally {
      setIsExporting(false);
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "s") {
        e.preventDefault();
        if (isEditorReady && !isSaving) {
          handleSaveClick();
        }
      }
      if ((e.metaKey || e.ctrlKey) && e.key === "z" && !e.shiftKey) {
        e.preventDefault();
        handleUndo();
      }
      if ((e.metaKey || e.ctrlKey) && e.shiftKey && e.key === "z") {
        e.preventDefault();
        handleRedo();
      }
      if ((e.metaKey || e.ctrlKey) && e.key === "e") {
        e.preventDefault();
        handleExportHtml();
      }
      if ((e.metaKey || e.ctrlKey) && e.key === "p") {
        e.preventDefault();
        handleExportPDF();
      }
      if (e.key === "Escape" && isFullscreen) {
        setIsFullscreen(false);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [
    isEditorReady,
    isSaving,
    isFullscreen,
    handleSaveClick,
    handleUndo,
    handleRedo,
    handleExportHtml,
    handleExportPDF,
  ]);

  const handleEditorReady = useCallback(
    (config: PDFStudioFullConfig | EmailStudioFullConfig) => {
      setIsEditorReady(true);
      setStudioConfig(config as PDFStudioFullConfig);

      if (!config.account.isConfigured) {
        toast.info("PDF Studio is running in free mode", {
          description: "Configure your Unlayer account for full features",
          duration: 4000,
          action: {
            label: "Setup",
            onClick: () => {},
          },
        });
      }
    },
    [],
  );

  const handleDesignUpdate = useCallback((design: UnlayerDesignJSON) => {
    setCurrentDesign(design);
    setHasUnsavedChanges(true);
  }, []);

  const handleConfirmSave = useCallback(async () => {
    if (!editorRef.current) return;

    setShowSaveDialog(false);
    setIsSaving(true);

    try {
      const exportData = await editorRef.current.exportHtml({
        minify: false,
        cleanup: true,
      });

      const payload = {
        name: metadata.name,
        description: metadata.description || undefined,
        design: exportData.design,
        html: exportData.html,
        category: metadata.category,
        page_size: metadata.pageSize,
        orientation: metadata.orientation,
        status: "draft",
      };

      const url = metadata.id
        ? `/api/pdf-templates/${metadata.id}`
        : "/api/pdf-templates";

      const method = metadata.id ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to save template");
      }

      const { template } = await response.json();

      setMetadata((prev) => ({ ...prev, id: template.id }));
      setHasUnsavedChanges(false);

      toast.success("Template saved", {
        description: `"${metadata.name}" has been saved successfully`,
        duration: 3000,
      });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Failed to save template";
      toast.error("Save failed", { description: message });
    } finally {
      setIsSaving(false);
    }
  }, [metadata]);

  const handleDelete = useCallback(async () => {
    if (!metadata.id) return;

    setShowDeleteDialog(false);

    try {
      const response = await fetch(`/api/pdf-templates/${metadata.id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to delete template");
      }

      toast.success("Template deleted");
      setMetadata({
        id: null,
        name: "Untitled Document",
        description: "",
        category: "custom",
        pageSize: "Letter",
        orientation: "portrait",
      });
      setCurrentDesign(null);
      if (editorRef.current) {
        editorRef.current.loadDesign(DEFAULT_DESIGN);
      }
      setHasUnsavedChanges(false);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Failed to delete template";
      toast.error("Delete failed", { description: message });
    }
  }, [metadata.id]);

  const handleCopyHtml = useCallback(() => {
    navigator.clipboard.writeText(exportedHtml);
    setCopiedHtml(true);
    toast.success("HTML copied to clipboard");
    setTimeout(() => setCopiedHtml(false), 2000);
  }, [exportedHtml]);

  const handleDownloadHtml = useCallback(() => {
    const blob = new Blob([exportedHtml], { type: "text/html" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${metadata.name.toLowerCase().replace(/\s+/g, "-")}.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    toast.success("HTML downloaded");
  }, [exportedHtml, metadata.name]);

  const handlePreview = useCallback((device: PreviewDevice) => {
    if (!editorRef.current) return;
    setPreviewDevice(device);
    editorRef.current.showPreview(device);
  }, []);

  const handleNewTemplate = useCallback(() => {
    setMetadata({
      id: null,
      name: "Untitled Document",
      description: "",
      category: "custom",
      pageSize: "Letter",
      orientation: "portrait",
    });
    setCurrentDesign(null);
    if (editorRef.current) {
      editorRef.current.loadDesign(DEFAULT_DESIGN);
    }
    setHasUnsavedChanges(false);
    toast.info("New document created");
  }, []);

  return (
    <div
      className={cn(
        "flex flex-col bg-background transition-all duration-300",
        isFullscreen
          ? "fixed inset-0 z-50 overflow-hidden"
          : "flex-1 min-h-0 overflow-hidden",
      )}
    >
      <header className="h-12 md:h-14 bg-background border-b border-border flex items-center justify-between px-2 md:px-4 shrink-0 z-20">
        <div className="flex items-center gap-2 md:gap-3 min-w-0">
          <div className="flex items-center gap-2">
            <div className="p-1.5 rounded-lg bg-violet-500/10 text-violet-600">
              <FileText className="h-4 w-4" />
            </div>
            <span className="hidden sm:inline text-xs font-semibold uppercase tracking-wider text-foreground">
              PDF Studio
            </span>
          </div>

          <div className="hidden md:block">
            <PDFStudioSetupStatus variant="badge" />
          </div>

          <Separator orientation="vertical" className="h-5 hidden md:block" />

          <div className="hidden lg:flex items-center gap-1 text-xs text-muted-foreground min-w-0">
            <span className="shrink-0">Templates</span>
            <ChevronRight className="h-3 w-3 shrink-0" />
            <span className="font-medium text-foreground truncate max-w-[180px]">
              {metadata.name}
            </span>
            {hasUnsavedChanges && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <span className="ml-1 h-2 w-2 rounded-full bg-amber-500 animate-pulse shrink-0" />
                </TooltipTrigger>
                <TooltipContent side="bottom">
                  <p>Unsaved changes</p>
                </TooltipContent>
              </Tooltip>
            )}
          </div>
        </div>

        <div className="flex items-center gap-1.5 md:gap-2">
          <div className="hidden xl:flex items-center gap-1 p-0.5 bg-muted rounded-lg">
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-7 w-7 p-0"
                  onClick={handleUndo}
                  disabled={!isEditorReady}
                >
                  <Undo2 className="h-3.5 w-3.5" />
                </Button>
              </TooltipTrigger>
              <TooltipContent side="bottom">
                <p>Undo</p>
                <Kbd className="ml-1.5">⌘Z</Kbd>
              </TooltipContent>
            </Tooltip>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-7 w-7 p-0"
                  onClick={handleRedo}
                  disabled={!isEditorReady}
                >
                  <Redo2 className="h-3.5 w-3.5" />
                </Button>
              </TooltipTrigger>
              <TooltipContent side="bottom">
                <p>Redo</p>
                <Kbd className="ml-1.5">⌘⇧Z</Kbd>
              </TooltipContent>
            </Tooltip>
          </div>

          <div className="hidden md:block">
            <ToggleGroup
              type="single"
              value={previewDevice}
              onValueChange={(value) =>
                value && handlePreview(value as PreviewDevice)
              }
              disabled={!isEditorReady}
              variant="outline"
              size="sm"
            >
              <Tooltip>
                <TooltipTrigger asChild>
                  <ToggleGroupItem
                    value="desktop"
                    className="h-7 px-2.5 data-[state=on]:bg-primary data-[state=on]:text-primary-foreground"
                  >
                    <Monitor className="h-3.5 w-3.5" />
                    <span className="hidden lg:inline ml-1.5 text-[10px] font-medium uppercase tracking-wider">
                      Desktop
                    </span>
                  </ToggleGroupItem>
                </TooltipTrigger>
                <TooltipContent side="bottom">Desktop preview</TooltipContent>
              </Tooltip>
              <Tooltip>
                <TooltipTrigger asChild>
                  <ToggleGroupItem
                    value="mobile"
                    className="h-7 px-2.5 data-[state=on]:bg-primary data-[state=on]:text-primary-foreground"
                  >
                    <Smartphone className="h-3.5 w-3.5" />
                    <span className="hidden lg:inline ml-1.5 text-[10px] font-medium uppercase tracking-wider">
                      Mobile
                    </span>
                  </ToggleGroupItem>
                </TooltipTrigger>
                <TooltipContent side="bottom">Mobile preview</TooltipContent>
              </Tooltip>
            </ToggleGroup>
          </div>

          <Separator orientation="vertical" className="h-5 hidden md:block" />

          <DropdownMenu>
            <Tooltip>
              <TooltipTrigger asChild>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-8 gap-1.5"
                    disabled={!isEditorReady || isExporting}
                  >
                    {isExporting ? (
                      <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-current border-t-transparent" />
                    ) : (
                      <Download className="h-3.5 w-3.5" />
                    )}
                    <span className="hidden sm:inline text-xs font-medium">
                      Export
                    </span>
                  </Button>
                </DropdownMenuTrigger>
              </TooltipTrigger>
              <TooltipContent side="bottom">Export options</TooltipContent>
            </Tooltip>
            <DropdownMenuContent align="end" className="w-52">
              <DropdownMenuItem onClick={handleExportPDF}>
                <FileDown className="h-4 w-4 mr-2" />
                Export as PDF
                <DropdownMenuShortcut>⌘P</DropdownMenuShortcut>
              </DropdownMenuItem>
              <DropdownMenuItem onClick={handleExportHtml}>
                <FileCode className="h-4 w-4 mr-2" />
                Export as HTML
                <DropdownMenuShortcut>⌘E</DropdownMenuShortcut>
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                onClick={() => toast.info("Print functionality coming soon")}
              >
                <Printer className="h-4 w-4 mr-2" />
                Print
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>

          <Button
            size="sm"
            onClick={handleSaveClick}
            disabled={!isEditorReady || isSaving}
            className="h-8 px-3 md:px-4 gap-1.5"
          >
            {isSaving ? (
              <>
                <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-current border-t-transparent" />
                <span className="hidden sm:inline text-xs font-medium">
                  Saving...
                </span>
              </>
            ) : (
              <>
                <Save className="h-3.5 w-3.5" />
                <span className="hidden sm:inline text-xs font-medium">
                  Save
                </span>
              </>
            )}
          </Button>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                <MoreHorizontal className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-52">
              <DropdownMenuItem onClick={handleNewTemplate}>
                <Plus className="h-4 w-4 mr-2" />
                New Document
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => toast.info("Template settings coming soon")}
              >
                <Settings className="h-4 w-4 mr-2" />
                Settings
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => toast.info("Load template coming soon")}
              >
                <FolderOpen className="h-4 w-4 mr-2" />
                Load Template
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => toast.info("Duplicate coming soon")}
              >
                <Copy className="h-4 w-4 mr-2" />
                Duplicate
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                onClick={() => toast.info("Version history coming soon")}
              >
                <History className="h-4 w-4 mr-2" />
                Version History
              </DropdownMenuItem>
              <DropdownMenuItem onClick={handleNewTemplate}>
                <RotateCcw className="h-4 w-4 mr-2" />
                Reset Template
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={() => setIsFullscreen(!isFullscreen)}>
                {isFullscreen ? (
                  <Minimize2 className="h-4 w-4 mr-2" />
                ) : (
                  <Maximize2 className="h-4 w-4 mr-2" />
                )}
                {isFullscreen ? "Exit Fullscreen" : "Fullscreen"}
                <DropdownMenuShortcut>Esc</DropdownMenuShortcut>
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                className="text-destructive focus:text-destructive"
                disabled={!metadata.id}
                onClick={() => setShowDeleteDialog(true)}
              >
                <Trash2 className="h-4 w-4 mr-2" />
                Delete Template
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </header>

      <div className="flex-1 relative overflow-hidden bg-muted/30">
        <UnlayerEditor
          mode="document"
          editorId="pdf-studio-editor"
          onReady={handleEditorReady}
          onDesignUpdate={handleDesignUpdate}
          ref={editorRef}
          className="absolute inset-0"
          appearance={{
            theme: "modern_light",
            panels: {
              tools: {
                dock: "right",
                collapsible: true,
                defaultUncollapsed: true,
              },
            },
          }}
        />
      </div>

      <Dialog open={showSaveDialog} onOpenChange={setShowSaveDialog}>
        <DialogContent className="sm:max-w-[520px]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <div className="p-2 rounded-lg bg-violet-500/10">
                <Save className="h-4 w-4 text-violet-600" />
              </div>
              {metadata.id ? "Update PDF Template" : "Save PDF Template"}
            </DialogTitle>
            <DialogDescription>
              Enter the details for your PDF template. These will help organize
              your documents.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-5 py-4">
            <div className="grid gap-2">
              <Label htmlFor="name" className="text-xs font-medium">
                Template Name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="name"
                value={metadata.name}
                onChange={(e) =>
                  setMetadata((prev) => ({ ...prev, name: e.target.value }))
                }
                placeholder="e.g., Annual Tax Receipt"
                className="h-10"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="grid gap-2">
                <Label htmlFor="category" className="text-xs font-medium">
                  Category
                </Label>
                <Select
                  value={metadata.category}
                  onValueChange={(value: PDFTemplateCategory) =>
                    setMetadata((prev) => ({ ...prev, category: value }))
                  }
                >
                  <SelectTrigger id="category" className="h-10">
                    <SelectValue placeholder="Select category" />
                  </SelectTrigger>
                  <SelectContent>
                    {PDF_TEMPLATE_CATEGORIES.map((cat) => (
                      <SelectItem key={cat.value} value={cat.value}>
                        {cat.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="grid gap-2">
                <Label htmlFor="pageSize" className="text-xs font-medium">
                  Page Size
                </Label>
                <Select
                  value={metadata.pageSize}
                  onValueChange={(value: "A4" | "Letter" | "Legal") =>
                    setMetadata((prev) => ({ ...prev, pageSize: value }))
                  }
                >
                  <SelectTrigger id="pageSize" className="h-10">
                    <SelectValue placeholder="Select size" />
                  </SelectTrigger>
                  <SelectContent>
                    {PAGE_SIZES.map((size) => (
                      <SelectItem key={size.value} value={size.value}>
                        {size.label} ({size.dimensions})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid gap-2">
              <Label htmlFor="orientation" className="text-xs font-medium">
                Orientation
              </Label>
              <Select
                value={metadata.orientation}
                onValueChange={(value: "portrait" | "landscape") =>
                  setMetadata((prev) => ({ ...prev, orientation: value }))
                }
              >
                <SelectTrigger id="orientation" className="h-10">
                  <SelectValue placeholder="Select orientation" />
                </SelectTrigger>
                <SelectContent>
                  {ORIENTATIONS.map((o) => (
                    <SelectItem key={o.value} value={o.value}>
                      {o.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="grid gap-2">
              <Label htmlFor="description" className="text-xs font-medium">
                Description
              </Label>
              <Textarea
                id="description"
                value={metadata.description}
                onChange={(e) =>
                  setMetadata((prev) => ({
                    ...prev,
                    description: e.target.value,
                  }))
                }
                placeholder="Brief description of this template's purpose..."
                className="h-20 resize-none text-sm"
              />
              <p className="text-[11px] text-muted-foreground">
                A brief description helps team members understand when to use
                this template.
              </p>
            </div>
          </div>
          <DialogFooter className="gap-2 sm:gap-0">
            <Button variant="outline" onClick={() => setShowSaveDialog(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleConfirmSave}
              disabled={!metadata.name.trim() || isSaving}
            >
              {isSaving ? (
                <>
                  <span className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent mr-2" />
                  Saving...
                </>
              ) : (
                <>
                  <Save className="h-4 w-4 mr-2" />
                  {metadata.id ? "Update Template" : "Save Template"}
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={showExportDialog} onOpenChange={setShowExportDialog}>
        <DialogContent className="sm:max-w-[680px]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <div className="p-2 rounded-lg bg-violet-500/10">
                <FileCode className="h-4 w-4 text-violet-600" />
              </div>
              Export HTML
            </DialogTitle>
            <DialogDescription className="flex items-center gap-2">
              Copy or download the generated HTML code for your document
              template.
              {studioConfig?.export.cleanupCss && (
                <span className="inline-flex items-center gap-1 text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-full text-[10px] font-medium">
                  <Sparkles className="h-3 w-3" />
                  Optimized
                </span>
              )}
            </DialogDescription>
          </DialogHeader>
          <div className="py-4">
            <div className="relative group">
              <div className="absolute top-3 right-3 z-10">
                <Button
                  variant="secondary"
                  size="sm"
                  className="h-7 px-2 opacity-0 group-hover:opacity-100 transition-opacity"
                  onClick={handleCopyHtml}
                >
                  {copiedHtml ? (
                    <Check className="h-3.5 w-3.5 mr-1 text-emerald-600" />
                  ) : (
                    <Copy className="h-3.5 w-3.5 mr-1" />
                  )}
                  {copiedHtml ? "Copied!" : "Copy"}
                </Button>
              </div>
              <pre className="bg-slate-950 text-slate-100 p-4 rounded-xl text-xs overflow-auto max-h-[320px] font-mono leading-relaxed">
                {exportedHtml.slice(0, 3000)}
                {exportedHtml.length > 3000 && (
                  <span className="text-slate-500">
                    {`\n\n... truncated (${(exportedHtml.length - 3000).toLocaleString()} more characters)`}
                  </span>
                )}
              </pre>
            </div>
            <div className="flex items-center justify-between mt-3 text-xs text-muted-foreground">
              <span>{exportedHtml.length.toLocaleString()} characters</span>
              <span className="flex items-center gap-1">
                <Layers className="h-3 w-3" />
                Ready for PDF conversion
              </span>
            </div>
          </div>
          <DialogFooter className="gap-2 sm:gap-0">
            <Button
              variant="outline"
              onClick={() => setShowExportDialog(false)}
            >
              Close
            </Button>
            <Button variant="outline" onClick={handleCopyHtml}>
              {copiedHtml ? (
                <Check className="h-4 w-4 mr-2 text-emerald-600" />
              ) : (
                <Copy className="h-4 w-4 mr-2" />
              )}
              {copiedHtml ? "Copied!" : "Copy HTML"}
            </Button>
            <Button onClick={handleDownloadHtml}>
              <Download className="h-4 w-4 mr-2" />
              Download
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <AlertCircle className="h-5 w-5 text-destructive" />
              Delete Template
            </AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete &ldquo;{metadata.name}&rdquo;?
              This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

import { Alert, AlertDescription, AlertTitle } from "@asym/ui/components/shadcn/alert";
import { Badge } from "@asym/ui/components/shadcn/badge";
import { Button } from "@asym/ui/components/shadcn/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  CardFooter,
} from "@asym/ui/components/shadcn/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@asym/ui/components/shadcn/dialog";
import { Input } from "@asym/ui/components/shadcn/input";
import { Label } from "@asym/ui/components/shadcn/label";
import { Progress } from "@asym/ui/components/shadcn/progress";
import { Separator } from "@asym/ui/components/shadcn/separator";
import { cn } from "@asym/ui/lib/utils";
import {
  Mail,
  Key,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  ExternalLink,
  Eye,
  EyeOff,
  Send,
  Shield,
  Globe,
  Info,
  Loader2,
  ArrowRight,
  ChevronRight,
  RefreshCw,
} from "lucide-react";
import React, { useState, useCallback } from "react";
import { toast } from "sonner";

import type {
  ConnectSendGridResponse,
  DeliverabilityWarning,
  SenderIdentity,
  DomainAuthentication,
} from "@asym/email/types";

type ConnectionStatus = "disconnected" | "connecting" | "connected" | "error";
type TestEmailStatus = "idle" | "sending" | "success" | "error";

interface ConnectionState {
  status: ConnectionStatus;
  apiKeyHint?: string;
  senderIdentities: SenderIdentity[];
  domainAuthentication: DomainAuthentication[];
  deliverabilityScore: number;
  warnings: DeliverabilityWarning[];
  error?: string;
}

export default function SendGridSettingsPage() {
  const [apiKey, setApiKey] = useState("");
  const [showApiKey, setShowApiKey] = useState(false);
  const [fromEmail, setFromEmail] = useState("");
  const [fromName, setFromName] = useState("");
  const [replyToEmail, setReplyToEmail] = useState("");

  const [connection, setConnection] = useState<ConnectionState>({
    status: "disconnected",
    senderIdentities: [],
    domainAuthentication: [],
    deliverabilityScore: 0,
    warnings: [],
  });

  const [showTestDialog, setShowTestDialog] = useState(false);
  const [testEmail, setTestEmail] = useState("");
  const [testStatus, setTestStatus] = useState<TestEmailStatus>("idle");
  const [testError, setTestError] = useState<string | null>(null);

  const handleConnect = useCallback(async () => {
    if (!apiKey || !fromEmail || !fromName) {
      toast.error("Please fill in all required fields");
      return;
    }

    setConnection((prev) => ({
      ...prev,
      status: "connecting",
      error: undefined,
    }));

    try {
      const response = await fetch("/api/email/connect", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          apiKey,
          defaultFromEmail: fromEmail,
          defaultFromName: fromName,
          replyToEmail: replyToEmail || undefined,
        }),
      });

      const data = (await response.json()) as ConnectSendGridResponse & {
        error?: string;
      };

      if (!data.success) {
        setConnection((prev) => ({
          ...prev,
          status: "error",
          error: data.error || "Failed to connect",
        }));
        toast.error("Connection failed", { description: data.error });
        return;
      }

      setConnection({
        status: "connected",
        apiKeyHint: apiKey.slice(-4),
        senderIdentities: data.senderIdentities || [],
        domainAuthentication: data.domainAuthentication || [],
        deliverabilityScore: data.deliverabilityScore || 0,
        warnings: data.warnings || [],
      });

      toast.success("SendGrid connected!", {
        description: "Your API key has been validated successfully",
      });
    } catch (error) {
      setConnection((prev) => ({
        ...prev,
        status: "error",
        error: "Network error. Please try again.",
      }));
      toast.error("Connection failed", { description: "Network error" });
    }
  }, [apiKey, fromEmail, fromName, replyToEmail]);

  const handleDisconnect = useCallback(() => {
    setConnection({
      status: "disconnected",
      senderIdentities: [],
      domainAuthentication: [],
      deliverabilityScore: 0,
      warnings: [],
    });
    setApiKey("");
    toast.info("SendGrid disconnected");
  }, []);

  const handleSendTest = useCallback(async () => {
    if (!testEmail) {
      toast.error("Please enter a test email address");
      return;
    }

    setTestStatus("sending");
    setTestError(null);

    try {
      const response = await fetch("/api/email/test-send", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          apiKey,
          toEmail: testEmail,
          fromEmail,
          fromName,
        }),
      });

      const data = (await response.json()) as {
        success: boolean;
        error?: string;
        message?: string;
      };

      if (!data.success) {
        setTestStatus("error");
        setTestError(data.error || "Failed to send test email");
        return;
      }

      setTestStatus("success");
      toast.success("Test email sent!", {
        description: `Check ${testEmail} for the test email`,
      });
    } catch {
      setTestStatus("error");
      setTestError("Network error. Please try again.");
    }
  }, [apiKey, testEmail, fromEmail, fromName]);

  const getScoreColor = (score: number) => {
    if (score >= 80) return "text-emerald-600";
    if (score >= 50) return "text-amber-600";
    return "text-red-600";
  };

  const getScoreLabel = (score: number) => {
    if (score >= 80) return "Excellent";
    if (score >= 50) return "Good";
    return "Needs Improvement";
  };

  return (
    <div className="container max-w-4xl py-8 space-y-8">
      <div className="flex items-start justify-between">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2.5 rounded-xl bg-gradient-to-br from-blue-500 to-blue-600 text-white shadow-lg shadow-blue-500/25">
              <Mail className="h-6 w-6" />
            </div>
            <h1 className="text-2xl font-bold text-slate-900">
              SendGrid Integration
            </h1>
          </div>
          <p className="text-slate-600 max-w-xl">
            Connect your SendGrid account to send transactional emails,
            newsletters, and marketing campaigns through your own email
            infrastructure.
          </p>
        </div>
        {connection.status === "connected" && (
          <Badge
            variant="outline"
            className="bg-emerald-50 text-emerald-700 border-emerald-200 gap-1.5 px-3 py-1.5"
          >
            <CheckCircle2 className="h-3.5 w-3.5" />
            Connected
          </Badge>
        )}
      </div>

      {connection.status === "connected" ? (
        <div className="space-y-6">
          <Card className="border-emerald-200 bg-gradient-to-br from-emerald-50/50 to-white">
            <CardHeader className="pb-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="p-2 rounded-lg bg-emerald-100 text-emerald-600">
                    <CheckCircle2 className="h-5 w-5" />
                  </div>
                  <div>
                    <CardTitle className="text-lg">Connection Active</CardTitle>
                    <CardDescription>
                      API Key: ••••••••{connection.apiKeyHint}
                    </CardDescription>
                  </div>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleDisconnect}
                  className="text-slate-600"
                >
                  Disconnect
                </Button>
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="p-4 rounded-xl bg-white border border-slate-200 text-center">
                  <div className="text-2xl font-bold text-slate-900">
                    {connection.senderIdentities.length}
                  </div>
                  <div className="text-xs text-slate-500 mt-1">
                    Verified Senders
                  </div>
                </div>
                <div className="p-4 rounded-xl bg-white border border-slate-200 text-center">
                  <div className="text-2xl font-bold text-slate-900">
                    {
                      connection.domainAuthentication.filter((d) => d.valid)
                        .length
                    }
                  </div>
                  <div className="text-xs text-slate-500 mt-1">
                    Auth Domains
                  </div>
                </div>
                <div className="p-4 rounded-xl bg-white border border-slate-200 text-center col-span-2">
                  <div
                    className={cn(
                      "text-2xl font-bold",
                      getScoreColor(connection.deliverabilityScore),
                    )}
                  >
                    {connection.deliverabilityScore}%
                  </div>
                  <div className="text-xs text-slate-500 mt-1">
                    Deliverability Score •{" "}
                    {getScoreLabel(connection.deliverabilityScore)}
                  </div>
                  <Progress
                    value={connection.deliverabilityScore}
                    className="mt-2 h-1.5"
                  />
                </div>
              </div>

              <div className="flex items-center gap-3 pt-2">
                <Button
                  onClick={() => {
                    setTestEmail("");
                    setTestStatus("idle");
                    setTestError(null);
                    setShowTestDialog(true);
                  }}
                  className="bg-blue-600 hover:bg-blue-700"
                >
                  <Send className="h-4 w-4 mr-2" />
                  Send Test Email
                </Button>
                <Button
                  variant="outline"
                  onClick={() =>
                    window.open("https://app.sendgrid.com", "_blank")
                  }
                >
                  <ExternalLink className="h-4 w-4 mr-2" />
                  SendGrid Dashboard
                </Button>
              </div>
            </CardContent>
          </Card>

          {connection.warnings.length > 0 && (
            <div className="space-y-3">
              <h3 className="font-semibold text-slate-900 flex items-center gap-2">
                <AlertTriangle className="h-4 w-4 text-amber-500" />
                Recommendations
              </h3>
              {connection.warnings.map((warning, index) => (
                <Alert
                  key={index}
                  variant={
                    warning.severity === "error" ? "destructive" : "default"
                  }
                  className={cn(
                    warning.severity === "warning" &&
                      "border-amber-200 bg-amber-50 text-amber-900",
                    warning.severity === "info" &&
                      "border-blue-200 bg-blue-50 text-blue-900",
                  )}
                >
                  {warning.severity === "error" && (
                    <XCircle className="h-4 w-4" />
                  )}
                  {warning.severity === "warning" && (
                    <AlertTriangle className="h-4 w-4 text-amber-600" />
                  )}
                  {warning.severity === "info" && (
                    <Info className="h-4 w-4 text-blue-600" />
                  )}
                  <AlertDescription className="flex items-center justify-between">
                    <span>{warning.message}</span>
                    {warning.helpUrl && (
                      <Button
                        variant="link"
                        size="sm"
                        className="h-auto p-0 text-inherit"
                        onClick={() => window.open(warning.helpUrl, "_blank")}
                      >
                        Learn more <ArrowRight className="h-3 w-3 ml-1" />
                      </Button>
                    )}
                  </AlertDescription>
                </Alert>
              ))}
            </div>
          )}

          {connection.senderIdentities.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="text-base flex items-center gap-2">
                  <Shield className="h-4 w-4 text-blue-600" />
                  Verified Sender Identities
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {connection.senderIdentities.map((sender) => (
                    <div
                      key={sender.id}
                      className="flex items-center justify-between p-3 rounded-lg bg-slate-50 border border-slate-200"
                    >
                      <div>
                        <div className="font-medium text-slate-900">
                          {sender.from_name}
                        </div>
                        <div className="text-sm text-slate-500">
                          {sender.from_email}
                        </div>
                      </div>
                      {sender.verified ? (
                        <Badge
                          variant="outline"
                          className="bg-emerald-50 text-emerald-700 border-emerald-200"
                        >
                          <CheckCircle2 className="h-3 w-3 mr-1" />
                          Verified
                        </Badge>
                      ) : (
                        <Badge
                          variant="outline"
                          className="bg-amber-50 text-amber-700 border-amber-200"
                        >
                          <AlertTriangle className="h-3 w-3 mr-1" />
                          Pending
                        </Badge>
                      )}
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {connection.domainAuthentication.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="text-base flex items-center gap-2">
                  <Globe className="h-4 w-4 text-blue-600" />
                  Domain Authentication
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {connection.domainAuthentication.map((domain) => (
                    <div
                      key={domain.id}
                      className="flex items-center justify-between p-3 rounded-lg bg-slate-50 border border-slate-200"
                    >
                      <div>
                        <div className="font-medium text-slate-900">
                          {domain.domain}
                        </div>
                        {domain.subdomain && (
                          <div className="text-sm text-slate-500">
                            Subdomain: {domain.subdomain}
                          </div>
                        )}
                      </div>
                      {domain.valid ? (
                        <Badge
                          variant="outline"
                          className="bg-emerald-50 text-emerald-700 border-emerald-200"
                        >
                          <CheckCircle2 className="h-3 w-3 mr-1" />
                          Authenticated
                        </Badge>
                      ) : (
                        <Badge
                          variant="outline"
                          className="bg-amber-50 text-amber-700 border-amber-200"
                        >
                          <AlertTriangle className="h-3 w-3 mr-1" />
                          Incomplete
                        </Badge>
                      )}
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}
        </div>
      ) : (
        <div className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Key className="h-5 w-5 text-slate-600" />
                Connect SendGrid
              </CardTitle>
              <CardDescription>
                Enter your SendGrid API key and sender information to get
                started.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              <Alert className="border-blue-200 bg-blue-50">
                <Info className="h-4 w-4 text-blue-600" />
                <AlertTitle className="text-blue-900">
                  Getting your API Key
                </AlertTitle>
                <AlertDescription className="text-blue-800">
                  <ol className="list-decimal list-inside space-y-1 mt-2">
                    <li>
                      Go to{" "}
                      <a
                        href="https://app.sendgrid.com/settings/api_keys"
                        target="_blank"
                        rel="noopener noreferrer"
                        className="underline font-medium"
                      >
                        SendGrid API Keys Settings
                      </a>
                    </li>
                    <li>Click &ldquo;Create API Key&rdquo;</li>
                    <li>
                      Select &ldquo;Restricted Access&rdquo; and enable{" "}
                      <strong>Mail Send</strong> permission
                    </li>
                    <li>Copy the generated key (starts with SG.)</li>
                  </ol>
                </AlertDescription>
              </Alert>

              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="apiKey" className="text-sm font-medium">
                    SendGrid API Key <span className="text-red-500">*</span>
                  </Label>
                  <div className="relative">
                    <Input
                      id="apiKey"
                      type={showApiKey ? "text" : "password"}
                      value={apiKey}
                      onChange={(e) => setApiKey(e.target.value)}
                      placeholder="SG.xxxxxxxxxxxxxxxxxxxx"
                      className="pr-10 font-mono text-sm"
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="absolute right-0 top-0 h-full px-3 hover:bg-transparent"
                      onClick={() => setShowApiKey(!showApiKey)}
                    >
                      {showApiKey ? (
                        <EyeOff className="h-4 w-4 text-slate-400" />
                      ) : (
                        <Eye className="h-4 w-4 text-slate-400" />
                      )}
                    </Button>
                  </div>
                  <p className="text-xs text-slate-500">
                    Your API key is encrypted and never stored in plain text.
                  </p>
                </div>

                <Separator />

                <div className="grid gap-4 md:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="fromEmail" className="text-sm font-medium">
                      From Email <span className="text-red-500">*</span>
                    </Label>
                    <Input
                      id="fromEmail"
                      type="email"
                      value={fromEmail}
                      onChange={(e) => setFromEmail(e.target.value)}
                      placeholder="hello@yourorg.com"
                    />
                    <p className="text-xs text-slate-500">
                      Must be a verified sender in SendGrid
                    </p>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="fromName" className="text-sm font-medium">
                      From Name <span className="text-red-500">*</span>
                    </Label>
                    <Input
                      id="fromName"
                      value={fromName}
                      onChange={(e) => setFromName(e.target.value)}
                      placeholder="Give Hope"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="replyTo" className="text-sm font-medium">
                    Reply-To Email{" "}
                    <span className="text-slate-400">(optional)</span>
                  </Label>
                  <Input
                    id="replyTo"
                    type="email"
                    value={replyToEmail}
                    onChange={(e) => setReplyToEmail(e.target.value)}
                    placeholder="support@yourorg.com"
                  />
                </div>
              </div>

              {connection.status === "error" && connection.error && (
                <Alert variant="destructive">
                  <XCircle className="h-4 w-4" />
                  <AlertTitle>Connection Failed</AlertTitle>
                  <AlertDescription>{connection.error}</AlertDescription>
                </Alert>
              )}
            </CardContent>
            <CardFooter className="flex justify-between border-t bg-slate-50/50 pt-6">
              <Button
                variant="outline"
                onClick={() =>
                  window.open("https://signup.sendgrid.com/", "_blank")
                }
              >
                <ExternalLink className="h-4 w-4 mr-2" />
                Create SendGrid Account
              </Button>
              <Button
                onClick={handleConnect}
                disabled={
                  !apiKey ||
                  !fromEmail ||
                  !fromName ||
                  connection.status === "connecting"
                }
                className="bg-blue-600 hover:bg-blue-700 min-w-[140px]"
              >
                {connection.status === "connecting" ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Connecting...
                  </>
                ) : (
                  <>
                    Connect SendGrid
                    <ChevronRight className="h-4 w-4 ml-2" />
                  </>
                )}
              </Button>
            </CardFooter>
          </Card>

          <Card className="border-dashed">
            <CardHeader>
              <CardTitle className="text-base">Before You Connect</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid gap-4 md:grid-cols-3">
                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-blue-100 text-blue-600 shrink-0">
                    <Key className="h-4 w-4" />
                  </div>
                  <div>
                    <div className="font-medium text-sm text-slate-900">
                      Create API Key
                    </div>
                    <p className="text-xs text-slate-500 mt-0.5">
                      With at least &ldquo;Mail Send&rdquo; permission
                    </p>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-emerald-100 text-emerald-600 shrink-0">
                    <Shield className="h-4 w-4" />
                  </div>
                  <div>
                    <div className="font-medium text-sm text-slate-900">
                      Verify Sender
                    </div>
                    <p className="text-xs text-slate-500 mt-0.5">
                      Verify your from email address
                    </p>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <div className="p-2 rounded-lg bg-purple-100 text-purple-600 shrink-0">
                    <Globe className="h-4 w-4" />
                  </div>
                  <div>
                    <div className="font-medium text-sm text-slate-900">
                      Authenticate Domain
                    </div>
                    <p className="text-xs text-slate-500 mt-0.5">
                      For best deliverability (recommended)
                    </p>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      <Dialog open={showTestDialog} onOpenChange={setShowTestDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Send className="h-5 w-5 text-blue-600" />
              Send Test Email
            </DialogTitle>
            <DialogDescription>
              Send a test email to verify your SendGrid configuration is working
              correctly.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="testEmail">Recipient Email</Label>
              <Input
                id="testEmail"
                type="email"
                value={testEmail}
                onChange={(e) => setTestEmail(e.target.value)}
                placeholder="your-email@example.com"
                disabled={testStatus === "sending"}
              />
            </div>

            <div className="p-3 rounded-lg bg-slate-50 border border-slate-200 text-sm">
              <div className="grid grid-cols-2 gap-2 text-slate-600">
                <span className="text-slate-500">From:</span>
                <span className="font-medium">
                  {fromName} &lt;{fromEmail}&gt;
                </span>
                <span className="text-slate-500">Subject:</span>
                <span className="font-medium">SendGrid Test Email</span>
              </div>
            </div>

            {testStatus === "success" && (
              <Alert className="border-emerald-200 bg-emerald-50">
                <CheckCircle2 className="h-4 w-4 text-emerald-600" />
                <AlertTitle className="text-emerald-800">
                  Email Sent!
                </AlertTitle>
                <AlertDescription className="text-emerald-700">
                  Check your inbox at {testEmail}
                </AlertDescription>
              </Alert>
            )}

            {testStatus === "error" && testError && (
              <Alert variant="destructive">
                <XCircle className="h-4 w-4" />
                <AlertTitle>Failed to Send</AlertTitle>
                <AlertDescription>{testError}</AlertDescription>
              </Alert>
            )}
          </div>

          <DialogFooter className="gap-2 sm:gap-0">
            <Button variant="outline" onClick={() => setShowTestDialog(false)}>
              {testStatus === "success" ? "Close" : "Cancel"}
            </Button>
            <Button
              onClick={handleSendTest}
              disabled={!testEmail || testStatus === "sending"}
              className="bg-blue-600 hover:bg-blue-700"
            >
              {testStatus === "sending" ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Sending...
                </>
              ) : testStatus === "success" ? (
                <>
                  <RefreshCw className="h-4 w-4 mr-2" />
                  Send Another
                </>
              ) : (
                <>
                  <Send className="h-4 w-4 mr-2" />
                  Send Test
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

